/* Tacho-Bogen: beginnt bei 7 Uhr, endet bei 17 Uhr — offener Bogen über 300°.
   In SVG-Winkeln entspricht 12 Uhr −90°, jede Stunde 30°: Start 120°.        */
const GAUGE_START = 120;
const GAUGE_SWEEP = 300;

function polar(cx, cy, r, deg) {
  const a = (deg * Math.PI) / 180;
  return [cx + r * Math.cos(a), cy + r * Math.sin(a)];
}

function arcPath(cx, cy, r, startDeg, sweepDeg) {
  const sweep = Math.max(0.01, Math.min(359.99, sweepDeg));
  const [x1, y1] = polar(cx, cy, r, startDeg);
  const [x2, y2] = polar(cx, cy, r, startDeg + sweep);
  // Ab 180° Bogenlänge muss large-arc-flag auf 1 stehen, sonst zeichnet der
  // Browser den kurzen Gegenbogen.
  const large = sweep > 180 ? 1 : 0;
  return `M ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2}`;
}

function Gauge({ pct, label, color, size = 104 }) {
  const stroke = Math.round(size * 0.115);
  const cx = size / 2;
  const cy = size / 2;
  const r = (size - stroke) / 2;
  return (
    <svg width={size} height={size} style={{ flexShrink: 0 }} aria-hidden="true">
      <path d={arcPath(cx, cy, r, GAUGE_START, GAUGE_SWEEP)}
        fill="none" stroke="#E3DED2" strokeWidth={stroke} strokeLinecap="butt" />
      <path d={arcPath(cx, cy, r, GAUGE_START, (GAUGE_SWEEP * pct) / 100)}
        fill="none" stroke={color} strokeWidth={stroke} strokeLinecap="butt" />
      <text x="50%" y="50%" textAnchor="middle" dominantBaseline="central"
        fontSize={size * 0.29} fontWeight="700" fill="#1B2430">{label}</text>
    </svg>
  );
}

function RadarTick({ x, y, cx, payload }) {
  const cat = CATEGORIES.find((c) => c.id === payload.value);
  const lines = cat ? cat.radar : [payload.value];
  const anchor = x > cx + 5 ? "start" : x < cx - 5 ? "end" : "middle";
  const dy0 = lines.length > 1 ? -6 : 0;
  return (
    <text x={x} y={y} textAnchor={anchor} fill="#3B4652" fontSize={13}>
      {lines.map((l, i) => <tspan key={i} x={x} dy={i === 0 ? dy0 : 12}>{l}</tspan>)}
    </text>
  );
}

