/* ═════════════════════════════ Schritt 2 — Quiz ═══════════════════════════ */

function Quiz({ current, qi, total, selected, onSelect, onNext, onBack, editMode }) {
  const pct = Math.round(((qi + 1) / total) * 100);
  const isLast = qi === total - 1;

  // Auf der letzten Frage und beim gezielten Nachbearbeiten bleibt der Knopf
  // stehen: dort ist der nächste Schritt kein blosser Frageweschsel.
  const autoAdvance = !editMode && !isLast;
  const timer = useRef(null);

  // Ausstehenden Sprung verwerfen, wenn die Frage wechselt oder die
  // Komponente verschwindet — sonst springt es nach einem Zurück-Klick weiter.
  useEffect(() => () => clearTimeout(timer.current), [qi]);

  function choose(v) {
    onSelect(v);
    if (!autoAdvance) return;
    // Kurze Pause, damit die getroffene Wahl noch sichtbar aufleuchtet.
    clearTimeout(timer.current);
    timer.current = setTimeout(onNext, 320);
  }

  return (
    <div style={styles.centerWrap}>
      <div style={{ ...styles.card, maxWidth: 520 }}>
        {editMode ? (
          <div style={styles.editBadge}><Pencil size={13} style={{ marginRight: 6 }} /> Einzelne Antwort bearbeiten</div>
        ) : (
          <div style={styles.progressRow}>
            <div style={styles.progressTrack}><div style={{ ...styles.progressFill, width: `${pct}%` }} /></div>
            <span style={styles.progressLabel}>{qi + 1} / {total}</span>
          </div>
        )}

        <div style={styles.tagRow}>
          <span style={styles.catTag}>{current.catName.toUpperCase()}</span>
          <span style={styles.nrTag}>Nr. {current.nr}</span>
        </div>

        <h2 style={styles.question}>{current.text}</h2>
        <p style={styles.questionExplain}>{current.explain}</p>

        <div style={styles.scaleWrap}>
          {SCALE.map((s) => {
            const active = selected === s.v;
            return (
              <button key={s.v}
                onClick={(e) => { choose(s.v); e.currentTarget.blur(); }}
                style={{ ...styles.scaleBtn, ...(active ? styles.scaleBtnActive : {}) }}>
                <span style={{ ...styles.scaleNum, ...(active ? styles.scaleNumActive : {}) }}>{s.v}</span>
                <span>{s.label}</span>
              </button>
            );
          })}
        </div>

        <div style={{ ...styles.navRow, justifyContent: autoAdvance ? "flex-start" : "space-between" }}>
          <button style={styles.linkBtn} onClick={() => { clearTimeout(timer.current); onBack(); }}>
            {editMode ? "Zurück zur Übersicht" : "Zurück"}
          </button>
          {!autoAdvance && (
            <button
              style={{ ...styles.primaryBtnInline, opacity: selected ? 1 : 0.45, cursor: selected ? "pointer" : "not-allowed" }}
              onClick={() => selected && onNext()} disabled={!selected}>
              {isLast && !editMode ? "Ergebnis anzeigen" : "Weiter"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ════════════════════ Schritt 2b — Übersicht / Korrektur ══════════════════ */

function Review({ answers, onEdit, onConfirm }) {
  const answered = allQuestions.filter((q) => answers[`${q.catId}-${q.qIndex}`]).length;
  const all = answered === allQuestions.length;
  return (
    <div style={{ ...styles.centerWrap, alignItems: "flex-start" }}>
      <div style={{ ...styles.card, maxWidth: 640 }}>
        <Eyebrows big="ÜBERPRÜFUNG" small={BRAND.product} />
        <h1 style={styles.h1}>Ihre Antworten im Überblick</h1>
        <p style={styles.lead}>
          Kontrollieren Sie Ihre Angaben. Mit „Bearbeiten“ können Sie einzelne Antworten korrigieren.
        </p>

        <div style={{ marginTop: 18 }}>
          {allQuestions.map((q, i) => {
            const val = answers[`${q.catId}-${q.qIndex}`];
            const label = SCALE.find((s) => s.v === val)?.label;
            return (
              <div key={i} style={styles.reviewRow}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={styles.reviewCat}>{q.catName}</div>
                  <div style={styles.reviewNr}>Frage {i + 1} von 15 · {q.keyword}</div>
                  <div style={styles.reviewQ}>{q.text}</div>
                  <div style={{ ...styles.reviewAnswer, color: val ? tierFor(val).color : "#C1392B" }}>
                    {val ? `${val} von 5 — ${label}` : "Nicht beantwortet"}
                  </div>
                </div>
                <button style={styles.editBtn} onClick={() => onEdit(i)}>
                  <Pencil size={13} style={{ marginRight: 5 }} /> Bearbeiten
                </button>
              </div>
            );
          })}
        </div>

        <button
          style={{ ...styles.primaryBtn, opacity: all ? 1 : 0.45, cursor: all ? "pointer" : "not-allowed" }}
          onClick={() => all && onConfirm()} disabled={!all}>
          Zurück zum Ergebnis
        </button>
        {!all && <div style={styles.warnLine}>Bitte beantworten Sie zuerst alle Fragen.</div>}
      </div>
    </div>
  );
}

