/* ══════════════════════ Schritt 5 — E-Mail-Gate ═══════════════════════════ */

function EmailGate({ email, setEmail, payload, onSent }) {
  const [state, setState] = useState("idle"); // idle | sending | error
  const [touched, setTouched] = useState(false);
  const valid = isValidEmail(email);

  async function submit() {
    setTouched(true);
    if (!valid || state === "sending") return;
    setState("sending");
    try {
      await callBackend(BACKEND.requestVerification, { email, ...payload });
      onSent();
    } catch (e) {
      setState("error");
    }
  }

  return (
    <div style={styles.centerWrap}>
      <div style={{ ...styles.card, maxWidth: 520, textAlign: "center" }}>
        <Wordmark />
        <Eyebrows big="Ihre persönliche Auswertung ist bereit" small={BRAND.product} />

        <h1 style={styles.h1}>Wohin dürfen wir Ihre Auswertung senden?</h1>

        <label style={{ ...styles.label, textAlign: "left" }} htmlFor="mail">E-Mail-Adresse*</label>
        <input id="mail" type="email" style={{ ...styles.input, ...(touched && !valid ? styles.inputError : {}) }}
          value={email} onChange={(e) => setEmail(e.target.value)}
          onBlur={() => setTouched(true)} placeholder="name@firma.ch" />
        {touched && !valid && (
          <div style={styles.fieldError}>Bitte eine gültige E-Mail-Adresse eingeben, z. B. name@firma.ch</div>
        )}

        <p style={styles.consentText}>
          Ihre Angaben und Ihr Ergebnis werden zur Erstellung Ihrer Auswertung an Adlatus
          übermittelt und gespeichert. <a href={PRIVACY_URL} style={styles.inlineLink}>Datenschutz</a>
        </p>

        <div style={styles.goldRuleWide} />

        <button style={{ ...styles.primaryBtn, opacity: state === "sending" ? 0.6 : 1 }}
          onClick={submit} disabled={state === "sending"}>
          {state === "sending" ? "Wird gesendet …" : "Meine Auswertung senden"}
        </button>

        {state === "error" && (
          <div style={styles.errorLine}>
            Die Übermittlung hat nicht geklappt. Bitte Internetverbindung prüfen und erneut versuchen.
          </div>
        )}

        <div style={styles.trustLine}>Vertraulich behandelt · keine Weitergabe an Dritte</div>
      </div>
    </div>
  );
}

/* ════════════════════ Schritt 5b — E-Mail-Verifizierung ═══════════════════ */

function Verify({ email, onConfirmed }) {
  const [resent, setResent] = useState(false);

  async function resend() {
    try { await callBackend(BACKEND.resendVerification, { email }); setResent(true); } catch (e) { setResent(true); }
  }

  return (
    <div style={styles.centerWrap}>
      <div style={{ ...styles.card, maxWidth: 520, textAlign: "center" }}>
        <Wordmark />
        <Eyebrows big="Fast geschafft" small={BRAND.product} />

        <div style={styles.mailCircle}><Mail size={22} color="#0F5C9E" /></div>

        <h1 style={styles.h1}>
          Bitte bestätigen Sie<br />
          Ihre E-Mail-Adresse
        </h1>
        <p style={styles.lead}>
          Wir haben Ihnen einen Bestätigungslink an <strong>{email}</strong> gesendet. Klicken Sie
          auf den Link in der E-Mail, um Ihre vollständige Auswertung zu öffnen. Der Link ist
          24 Stunden gültig.
        </p>

        <div style={styles.goldRuleWide} />

        <div style={styles.resendHint}>Keine E-Mail erhalten? Bitte auch im Spam-Ordner nachsehen.</div>
        <button style={styles.linkBtnCenter} onClick={resend}>E-Mail erneut senden</button>
        {resent && <div style={styles.resentOk}>E-Mail wurde erneut versendet.</div>}

        {/* ────────────────────────────────────────────────────────────────
            PROVISORISCH — bis das Backend steht.
            Der echte Weg führt über den Link in der Bestätigungsmail auf
            eine Seite, die den Token prüft und dann den Bericht öffnet.
            Diesen Block entfernen, sobald der Endpoint existiert.
            ──────────────────────────────────────────────────────────── */}
        <div className="dev-only" style={styles.devBox}>
          <div style={styles.devLabel}>Testmodus — noch kein Backend angebunden</div>
          <button style={styles.smallBtn} onClick={onConfirmed}>Bestätigung überspringen</button>
        </div>
      </div>
    </div>
  );
}

