// Aufhellen einer Stufenfarbe für Flächen — der Text muss lesbar bleiben,
// deshalb bewusst sehr schwach getönt.
function tint(hex, alpha) {
  const h = hex.replace("#", "");
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function AreaCard({ area }) {
  const t = tierFor(area.avg);
  const block = area[t.key];
  const withActions = showsActions(t.key);
  return (
    <div style={{
      ...styles.areaCard,
      background: tint(t.color, 0.07),
      borderColor: tint(t.color, 0.4),
    }}>
      <div style={styles.areaName}>{area.name}</div>
      <div style={styles.areaScore}>{fmt(area.avg)} von 5 · <span style={{ color: t.color, fontWeight: 600 }}>{t.label}</span></div>
      
      <div style={styles.areaSituation}>{block.situation}</div>
      {withActions && (
        <>
          <div style={styles.actionHead}>Mögliche Handlungsimpulse</div>
          {block.actions.map((a, i) => (
            <div key={i} style={styles.actionRow}>
              <Check size={12} color={t.color} style={{ flexShrink: 0, marginTop: 3 }} />
              <span>{a}</span>
            </div>
          ))}
        </>
      )}
    </div>
  );
}

/* ══════════════════════ Schritt 7 — Conversion ════════════════════════════ */

function Conversion({ company, email, onRestart }) {
  const [choice, setChoice] = useState("yes");
  const [form, setForm] = useState({ vorname: "", nachname: "", unternehmen: company || "", telefon: "", nachricht: "" });
  const [touched, setTouched] = useState(false);
  const [state, setState] = useState("idle"); // idle | sending | done | error
  const [news, setNews] = useState(false);
  const [newsState, setNewsState] = useState("idle");

  const required = ["vorname", "nachname", "unternehmen", "telefon"];
  const missing = required.filter((f) => !form[f].trim());
  const complete = missing.length === 0;

  const set = (f) => (e) => setForm({ ...form, [f]: e.target.value });

  async function submitCall() {
    setTouched(true);
    if (!complete || state === "sending") return;
    setState("sending");
    try {
      await callBackend(BACKEND.submitConversion, { wantsCall: true, email, ...form });
      setState("done");
    } catch (e) { setState("error"); }
  }

  async function submitNews() {
    if (!news || newsState === "sending") return;
    setNewsState("sending");
    try {
      await callBackend(BACKEND.newsletterSignup, { email });
      setNewsState("done");
    } catch (e) { setNewsState("error"); }
  }

  return (
    <div style={styles.centerWrap}>
      <div style={{ ...styles.card, maxWidth: 520 }}>
        <Wordmark />
        <Eyebrows big="Ihre Auswertung zeigt erste Chancen auf." small={BRAND.product} />

        <h1 style={styles.h1}>Möchten Sie Ihre Ergebnisse persönlich besprechen?</h1>
        <p style={styles.lead}>
          Nutzen Sie ein kostenloses 45-Minuten-Erstgespräch mit einem erfahrenen Adlatus-Berater,
          um Ihre wichtigsten Entwicklungspotenziale zu besprechen und mögliche nächste Schritte
          zu klären.
        </p>

        {state !== "done" && (
          <div style={{ marginTop: 18 }}>
            {[
              { v: "yes", label: "Ja, kostenloses Erstgespräch anfragen" },
              { v: "no", label: "Nein, im Moment nicht" },
            ].map((o) => (
              <button key={o.v} onClick={() => setChoice(o.v)}
                style={{ ...styles.radioRow, ...(choice === o.v ? styles.radioRowActive : {}) }}>
                <span style={{ ...styles.radioDot, ...(choice === o.v ? styles.radioDotActive : {}) }} />
                <span>{o.label}</span>
              </button>
            ))}
          </div>
        )}

        {/* ───────── Ja-Panel ───────── */}
        {choice === "yes" && state !== "done" && (
          <div style={{ marginTop: 16 }}>
            <Field label="Was möchten Sie besonders besprechen? (optional)" value={form.nachricht}
              onChange={set("nachricht")} textarea
              placeholder="z. B. Strategie, Organisation, Markt, Unternehmungssteuerung, Nachfolge …" />
            <Field label="Vorname*" value={form.vorname} onChange={set("vorname")}
              error={touched && !form.vorname.trim()} />
            <Field label="Nachname*" value={form.nachname} onChange={set("nachname")}
              error={touched && !form.nachname.trim()} />
            <Field label="Unternehmen*" value={form.unternehmen} onChange={set("unternehmen")}
              error={touched && !form.unternehmen.trim()} />
            <Field label="Telefonnummer*" value={form.telefon} onChange={set("telefon")}
              placeholder="079 000 00 00" error={touched && !form.telefon.trim()} />

            <div style={styles.requiredHint}>* Pflichtfeld</div>
            {touched && !complete && (
              <div style={styles.fieldError}>Bitte alle Pflichtfelder ausfüllen, damit wir Sie erreichen können.</div>
            )}

            <button style={{ ...styles.primaryBtn, opacity: state === "sending" ? 0.6 : 1 }}
              onClick={submitCall} disabled={state === "sending"}>
              {state === "sending" ? "Wird gesendet …" : "Gespräch anfragen"}
            </button>
            <div style={styles.metaLineQuiet}>Wir melden uns innert drei Tagen bei Ihnen.</div>
            {state === "error" && (
              <div style={styles.errorLine}>
                Die Anfrage konnte nicht gesendet werden. Bitte erneut versuchen oder direkt
                an {CONTACT.mail} schreiben.
              </div>
            )}
          </div>
        )}

        {state === "done" && (
          <div style={styles.successBox}>
            <Check size={17} color="#1F6B3A" style={{ flexShrink: 0, marginTop: 2 }} />
            <span>Anfrage gesendet. Wir melden uns in Kürze.</span>
          </div>
        )}

        {/* ───────── Nein-Panel ───────── */}
        {choice === "no" && state !== "done" && (
          <div style={{ marginTop: 20 }}>
            <div style={styles.colTitle}>Vielen Dank für Ihr Interesse</div>
            <p style={styles.lead}>Ihre Company-Compass-Auswertung haben Sie bereits per E-Mail erhalten.</p>

            <div style={styles.goldRuleWide} />

            <div style={styles.impulseQ}>Möchten Sie gelegentlich weitere Impulse für Ihr Unternehmen erhalten?</div>
            <label style={styles.checkboxRow}>
              <input type="checkbox" checked={news} onChange={(e) => setNews(e.target.checked)} style={{ marginTop: 3 }} />
              <span>Ja, ich möchte gelegentlich praxisnahe Impulse und Informationen von Adlatus per E-Mail erhalten.</span>
            </label>

            {newsState === "done" ? (
              <div style={styles.successBox}>
                <Check size={17} color="#1F6B3A" style={{ flexShrink: 0, marginTop: 2 }} />
                <span>Danke, Sie erhalten künftig gelegentlich Impulse von uns.</span>
              </div>
            ) : (
              <button style={{ ...styles.primaryBtn, opacity: news ? 1 : 0.45, cursor: news ? "pointer" : "not-allowed" }}
                onClick={submitNews} disabled={!news || newsState === "sending"}>
                {newsState === "sending" ? "Wird gesendet …" : "Anmelden"}
              </button>
            )}

            <div style={styles.fineprint}>
              Sie können sich jederzeit wieder abmelden. <a href={PRIVACY_URL} style={styles.inlineLink}>Datenschutz</a>
            </div>
            <div style={styles.quietNote}>
              Sie möchten später doch ein Gespräch? Eine Kontaktmöglichkeit finden Sie in Ihrer Auswertung.
            </div>
          </div>
        )}

        <div style={styles.introFooter}>
          <div>{FOOTER.line1}</div>
          <div>
            {FOOTER.line2}
            <span style={styles.buildLine}> · {FOOTER.build}</span>
          </div>
        </div>

        <button style={styles.linkBtnCenter} onClick={onRestart}>
          <RotateCcw size={13} style={{ marginRight: 6 }} /> Neue Analyse starten
        </button>
      </div>
    </div>
  );
}

function Field({ label, value, onChange, placeholder, textarea, error }) {
  return (
    <div style={{ marginBottom: 12 }}>
      <label style={styles.fieldLabel}>{label}</label>
      {textarea ? (
        <textarea style={{ ...styles.input, minHeight: 62, resize: "vertical", ...(error ? styles.inputError : {}) }}
          value={value} onChange={onChange} placeholder={placeholder} />
      ) : (
        <input style={{ ...styles.input, ...(error ? styles.inputError : {}) }}
          value={value} onChange={onChange} placeholder={placeholder} />
      )}
    </div>
  );
}

